    Amount: 'தொகை',
    'An estimate based on {from}. You’ll know the exact price before any work starts.':
      '{from} வைச்சு மதிப்பீடு. வேலை தொடங்குறதுக்கு முன்னாடி சரியான விலை தெரியும்.',
    'Ask a question': 'கேள்வி கேளுங்க',
    'Ask for a visit': 'விசிட் கேளுங்க',
    'Ask {owner} a question': '{owner}-கிட்ட கேள்வி கேளுங்க',
    'Asked for a site visit before going ahead.':
      'தொடங்குறதுக்கு முன்னாடி நேரில் வந்து பார்க்கச் சொன்னீங்க.',
    'Based on what you told us.': 'நீங்க சொன்னதை வைச்சு.',
    'Based on {from} and what you told us.': '{from} மற்றும் நீங்க சொன்னதை வைச்சு.',
