    'Email me a copy': 'எனக்கு ஒரு காப்பி அனுப்புங்க',
    Estimate: 'மதிப்பீடு',
    'Estimate from {business}': '{business}-ல இருந்து மதிப்பீடு',
    'Film a quick walk-around and we’ll count and measure from it':
      'சுத்தி ஒரு சின்ன வீடியோ எடுங்க, அதை வச்சு அளந்துக்குறோம்',
