    'Here’s your quote from {business} for {price}. See what’s included and accept it here:':
      'మీకు {business} నుండి {price} కి కొటేషన్ ఇదిగో. ఏమున్నాయో చూసి ఇక్కడే ఓకే చేయండి:',
    'Here’s your quote, {first}.': 'ఇదిగో మీ కొటేషన్, {first}.',
    'Here’s your quote.': 'ఇదిగో మీ కొటేషన్.',
    'Hi {first},': 'హాయ్ {first},',
    "Hi! I'm the quote assistant for {business}. I can put a price together for you in a couple of minutes, then {owner} takes it from there. What do you need done?":
      'హాయ్! నేను {business} కొటేషన్ అసిస్టెంట్‌ని. రెండు నిమిషాల్లో మీకు ధర చెప్తాను, ఆ తర్వాత {owner} చూసుకుంటారు. మీకు ఏం చేయాలి?',
    "Hi! I'm the quote assistant for {business}. I can put a price together for you in a couple of minutes. What do you need done?":
      'హాయ్! నేను {business} కొటేషన్ అసిస్టెంట్‌ని. రెండు నిమిషాల్లో మీకు ధర చెప్తాను. మీకు ఏం చేయాలి?',
    'Hi,': 'హాయ్,',
    'I can read messages, photos and videos here, but not files.':
      'నేను ఇక్కడ మెసేజ్‌లు, ఫోటోలు, వీడియోలు చూడగలను, ఫైళ్లు చూడలేను.',
    'I can’t watch videos here yet. Could you send a photo or two instead?':
      'నేను ఇక్కడ వీడియోలు చూడలేను. ఒకట్రెండు ఫోటోలు పంపగలరా?',
    'I couldn’t make out that voice note. Could you type it instead?':
      'ఆ వాయిస్ నోట్ నాకు అర్థం కాలేదు. టైప్ చేసి పంపగలరా?',
    'In your photos:': 'మీ ఫోటోల్లో:',
